# ==============================================================================# 077_CAPABILITY_RESEARCH_AGENT.py## IOTEC CAPABILITY RESEARCH AGENT## Missão:# Pesquisar alternativas para adquirir capacidades.## NÃO instala.# NÃO modifica.# NÃO toma decisão.## Apenas produz um dossiê técnico.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CapabilityResearchAgent:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS capability_research(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            research_id TEXT,            capability TEXT,            candidate_name TEXT,            provider TEXT,            category TEXT,            description TEXT,            maturity TEXT,            integration_level TEXT,            estimated_cost TEXT,            security_level TEXT,            commercial_score REAL,            technical_score REAL,            governance_score REAL,            recommendation TEXT,            status TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_candidate(        self,        capability,        candidate_name,        provider,        category,        description,        maturity,        integration_level,        estimated_cost,        security_level,        commercial_score,        technical_score,        governance_score,        recommendation,        metadata=None    ):        metadata=metadata or {}        timestamp=datetime.utcnow().isoformat()        research_id=hashlib.md5(            f"{timestamp}{candidate_name}".encode()        ).hexdigest()        payload={            "timestamp":timestamp,            "research_id":research_id,            "capability":capability,            "candidate_name":candidate_name,            "provider":provider,            "category":category,            "description":description,            "maturity":maturity,            "integration_level":integration_level,            "estimated_cost":estimated_cost,            "security_level":security_level,            "commercial_score":commercial_score,            "technical_score":technical_score,            "governance_score":governance_score,            "recommendation":recommendation,            "status":"UNDER_REVIEW",            "metadata":metadata        }        assinatura=self._hash(payload)        self.conn.execute("""        INSERT INTO capability_research(            timestamp,            research_id,            capability,            candidate_name,            provider,            category,            description,            maturity,            integration_level,            estimated_cost,            security_level,            commercial_score,            technical_score,            governance_score,            recommendation,            status,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["research_id"],            payload["capability"],            payload["candidate_name"],            payload["provider"],            payload["category"],            payload["description"],            payload["maturity"],            payload["integration_level"],            payload["estimated_cost"],            payload["security_level"],            payload["commercial_score"],            payload["technical_score"],            payload["governance_score"],            payload["recommendation"],            payload["status"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=CapabilityResearchAgent()    resultado=engine.register_candidate(        capability="BASE_EMPRESARIAL",        candidate_name="CATALOGO_EMPRESARIAL",        provider="EM PESQUISA",        category="INTELIGÊNCIA COMERCIAL",        description="Alternativa para ampliar a capacidade de prospecção empresarial.",        maturity="EM ANÁLISE",        integration_level="ALTA",        estimated_cost="A DEFINIR",        security_level="EM AVALIAÇÃO",        commercial_score=0,        technical_score=0,        governance_score=0,        recommendation="AGUARDANDO PESQUISA",        metadata={            "origin":"076_CAPABILITY_DISCOVERY_ENGINE",            "status":"RESEARCH_STARTED"        }    )    print("="*80)    print("CAPABILITY RESEARCH")    print("="*80)    for k,v in resultado.items():        print(f"{k:22}: {v}")    print("="*80)